BODY_FONT = 'Times New Roman'
BODY_SIZE = Pt(14)
TABLE_SIZE = Pt(12)
FIRST_LINE = Cm(1.25)
LINE_SPACING = 1.5


def set_run_font(run, *, bold=None, italic=None, size=BODY_SIZE, name=BODY_FONT):
    run.font.name = name
    run._element.rPr.rFonts.set(qn('w:ascii'), name)
    run._element.rPr.rFonts.set(qn('w:hAnsi'), name)
    run._element.rPr.rFonts.set(qn('w:cs'), name)
    run.font.size = size
    if bold is not None:
        run.bold = bold
    if italic is not None:
        run.italic = italic


def format_body_paragraph(p):
    p.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
    p.paragraph_format.first_line_indent = FIRST_LINE
    p.paragraph_format.line_spacing = LINE_SPACING
    p.paragraph_format.space_before = Pt(0)
    p.paragraph_format.space_after = Pt(0)
    for run in p.runs:
        set_run_font(run)


def format_heading_paragraph(p, *, center=False, before=6, after=6):
    p.alignment = WD_ALIGN_PARAGRAPH.CENTER if center else WD_ALIGN_PARAGRAPH.LEFT
    p.paragraph_format.first_line_indent = None
    p.paragraph_format.line_spacing = LINE_SPACING
    p.paragraph_format.space_before = Pt(before)
    p.paragraph_format.space_after = Pt(after)
    for run in p.runs:
        set_run_font(run, bold=True)


def format_caption_paragraph(p):
    p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    p.paragraph_format.first_line_indent = None
    p.paragraph_format.line_spacing = LINE_SPACING
    p.paragraph_format.space_before = Pt(0)
    p.paragraph_format.space_after = Pt(0)
    for run in p.runs:
        set_run_font(run)


def add_body(doc: Document, text: str):
    p = doc.add_paragraph(text)
    format_body_paragraph(p)
    return p


def add_heading(doc: Document, text: str, *, level: int = 1):
    p = doc.add_paragraph()
    run = p.add_run(text)
    set_run_font(run, bold=True)
    if level == 1:
        format_heading_paragraph(p, center=True, before=12, after=6)
    elif level == 2:
        format_heading_paragraph(p, center=False, before=6, after=6)
    else:
        format_heading_paragraph(p, center=False, before=6, after=3)
    return p


def add_caption(doc: Document, text: str):
    p = doc.add_paragraph(text)
    format_caption_paragraph(p)
    return p


def add_picture_with_caption(doc: Document, image_path: Path, caption: str, *, width_cm: float = 16.0):
    if not image_path.exists():
        add_body(doc, f'[{caption}: файл изображения {image_path.name} не найден и не был вставлен в документ.]')
        return
    p = doc.add_paragraph()
    p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    run = p.add_run()
    run.add_picture(str(image_path), width=Cm(width_cm))
    add_caption(doc, caption)


def shade_cell(cell, fill: str):
    tc_pr = cell._tc.get_or_add_tcPr()
    shd = OxmlElement('w:shd')
    shd.set(qn('w:fill'), fill)
    tc_pr.append(shd)


def set_cell_text(cell, text: str, *, bold=False, align='left', size=TABLE_SIZE):
    cell.text = ''
    p = cell.paragraphs[0]
    p.alignment = {
        'left': WD_ALIGN_PARAGRAPH.LEFT,
        'center': WD_ALIGN_PARAGRAPH.CENTER,
        'right': WD_ALIGN_PARAGRAPH.RIGHT,
        'justify': WD_ALIGN_PARAGRAPH.JUSTIFY,
    }[align]
    p.paragraph_format.first_line_indent = None
    p.paragraph_format.line_spacing = 1.0
    p.paragraph_format.space_before = Pt(0)
    p.paragraph_format.space_after = Pt(0)
    run = p.add_run(str(text))
    set_run_font(run, bold=bold, size=size)
    cell.vertical_alignment = WD_ALIGN_VERTICAL.CENTER


def add_table(doc: Document, caption: str, headers: list[str], rows: list[list[str]], *, col_widths_cm: list[float] | None = None):
    add_caption(doc, caption)
    table = doc.add_table(rows=1, cols=len(headers))
    table.style = 'Table Grid'
    table.alignment = WD_TABLE_ALIGNMENT.CENTER
    hdr = table.rows[0].cells
    for idx, text in enumerate(headers):
        set_cell_text(hdr[idx], text, bold=True, align='center', size=TABLE_SIZE)
        shade_cell(hdr[idx], 'D9EAF7')
        if col_widths_cm and idx < len(col_widths_cm):
            hdr[idx].width = Cm(col_widths_cm[idx])
    for row in rows:
        cells = table.add_row().cells
        for idx, text in enumerate(row):
            align = 'center' if idx and len(str(text)) < 18 else 'left'
            set_cell_text(cells[idx], text, align=align, size=TABLE_SIZE)
            if col_widths_cm and idx < len(col_widths_cm):
                cells[idx].width = Cm(col_widths_cm[idx])
    doc.add_paragraph('')
    return table


def remove_paragraph(paragraph):
    p = paragraph._element
    p.getparent().remove(p)
    paragraph._p = paragraph._element = None


def strip_chapter_body(doc: Document):
    start_idx = None
    for i, p in enumerate(doc.paragraphs):
        if p.text.strip() == '3 Разработка программного модуля СППР для диагностики серверного оборудования':
            # second occurrence after contents
            if start_idx is None:
                start_idx = i
            else:
                start_idx = i
                break
    if start_idx is None:
        raise RuntimeError('Не удалось найти начало реальной 3 главы в var1.docx')
    for p in list(doc.paragraphs[start_idx:]):
        remove_paragraph(p)


def ensure_default_normal_style(doc: Document):
    style = doc.styles['Normal']
    style.font.name = BODY_FONT
    style.font.size = BODY_SIZE
    style._element.rPr.rFonts.set(qn('w:ascii'), BODY_FONT)
    style._element.rPr.rFonts.set(qn('w:hAnsi'), BODY_FONT)
    style._element.rPr.rFonts.set(qn('w:cs'), BODY_FONT)
    style.paragraph_format.first_line_indent = FIRST_LINE
    style.paragraph_format.line_spacing = LINE_SPACING


def paragraph_block(text: str) -> list[str]:
    return [chunk.strip() for chunk in text.strip().split('\n\n') if chunk.strip()]


INTRO_PARAGRAPHS = paragraph_block('''
Третья глава посвящена проектированию, программной реализации и экспериментальной проверке разработанного программного комплекса поддержки принятия решений при риске и неопределённости для мониторинга и диагностики серверного оборудования. В отличие от обзорной постановки, характерной для предыдущих редакций текста, в данном разделе рассматривается не абстрактная схема методов, а реально реализованная система TechTracker, включающая контур сбора телеметрии, локальный статистический прогноз, удалённый нейросетевой прогноз, модуль оркестрации, единый модуль оценки состояния S0/S1/S2, подсистему оценки риска отказа, СППР выбора действия и модуль диссертационной верификации качества.

Ключевая идея реализованной системы состоит в переходе от реактивного администрирования по факту превышения порога к прогностическому управлению: система не ограничивается фиксацией текущего отклонения метрики, а строит траекторию будущих значений, оценивает вероятность ухудшения состояния оборудования, формирует интегральную оценку риска и предлагает действие, минимизирующее ожидаемые потери. Такой подход принципиально важен для серверной инфраструктуры, где цена пропущенного ухудшения часто выше цены ложной тревоги, а решение должно приниматься до наступления отказа.
''')

SEC31_PARAGRAPHS = paragraph_block('''
Разрабатываемый программный модуль рассматривается как эксплуатационная подсистема, встраиваемая в корпоративный контур мониторинга серверов и работающая поверх накопленной телеметрии. На вход подсистемы поступают сырые измерения эксплуатационных метрик, а на выходе формируется полный управленческий пакет: прогнозные точки по каждому горизонту, вероятности состояний S0/S1/S2, интегральная оценка риска отказа, ранжирование допустимых действий и итоговая рекомендация для оператора.

В рамках данной работы под диагностикой понимается не поиск аномалий в узком смысле и не реакция на единичный выход метрики за жёсткую границу. Диагностика трактуется как последовательная процедура оценки текущего и будущего функционального состояния узла, построенная на телеметрии, истории поведения системы и модели ожидаемых последствий управленческих решений. Такое определение согласуется с тем, как система реализована в проекте: прогноз, риск и рекомендация являются частями одного вычислительного цикла и не работают изолированно друг от друга.

Формально в каждый момент времени t наблюдается вектор серверных метрик X(t) = {x_1(t), x_2(t), …, x_n(t)}, где компонентами выступают загрузка процессора, использование оперативной памяти, сетевой трафик, задержка до шлюза, температура системы, температура дисков и счётчики деградации RAID-подсистемы. Для каждого выбранного горизонта h требуется построить не только терминальную оценку \u005eX(t+h), но и дискретную траекторию прогноза \u005eX(t+1), \u005eX(t+2), …, \u005eX(t+h), синхронизированную с шагом агрегации телеметрии. Именно переход от одной точки к траектории стал принципиальным инженерным улучшением проекта: он позволил использовать в оценке состояния и риска не только финальный прогноз, но и характер его изменения по всему горизонту.

С практической точки зрения система должна отвечать на четыре управленческих вопроса. Первый вопрос: насколько свежи и пригодны текущие данные для анализа. Второй вопрос: какие значения примут ключевые метрики через 24 часа, 7 суток и 30 суток, и с какой неопределённостью связан этот прогноз. Третий вопрос: во что преобразуется этот прогноз в терминах деградации состояния и риска отказа. Четвёртый вопрос: какое действие в текущем контексте минимизирует ожидаемые потери, учитывая ограничения на резервный ресурс, окно обслуживания, обратимость действия и операционные затраты.

Важное требование, возникшее уже на этапе развития проекта, связано с разделением вычислительного контура. Корпоративный сервер, на котором развёрнут основной backend и база данных, не должен выполнять тяжёлое обучение нейросетевой модели. Поэтому архитектура была перестроена так, чтобы статистический SARIMA-baseline, расчёт риска, оценка состояния, принятие решения и формирование отчётности выполнялись локально, а вычислительно затратный LSTM-прогноз запускался на отдельном удалённом ПК, связанном с системой через защищённый сетевой канал и вызываемом только backend-уровнем.

Из этого ограничения напрямую следуют нефункциональные требования. Во-первых, система обязана сохранять работоспособность при временной недоступности удалённого LSTM-сервиса и уметь продолжить работу хотя бы на статистической ветви прогноза. Во-вторых, повторная постановка удалённой задачи должна быть идемпотентной, иначе сбой сети приведёт к потере или дублированию результатов. В-третьих, весь расчёт должен быть воспроизводимым: необходимо фиксировать параметры запуска, версии моделей, число использованных точек истории, режим сезонности SARIMA, конфигурацию удалённого LSTM и итоговые показатели качества. Именно по этой причине в проект были добавлены отдельные сущности `ForecastRun`, `ForecastPoint`, `LSTMRemoteQueueJob`, `StateEstimate` и артефакты диссертационной верификации.

Функциональные требования к модулю можно сгруппировать следующим образом: приём и хранение метрик; предобработка и нормализация; многогоризонтное прогнозирование несколькими методами; интеграция прогнозов; оценка состояния и риска; выбор действия; контроль эффекта; экспорт отчётности. Наличие полного контура отличает разработанную систему от традиционной панели мониторинга: здесь визуализация не является конечной целью, а служит интерфейсом к вычислительным моделям и результатам СППР.
''')

